# Private relocation scheduling helpers, inserted before buildRelocationPlan.
s = once(s, '''function resetLocalRelocationPlan(){localRelocationPlan=null;}\nfunction relocationCellKey(x,y){return `${x},${y}`;}\nfunction buildRelocationPlan(start){\n''', '''function resetLocalRelocationPlan(){localRelocationPlan=null;}\nfunction resetLocalRelocationSchedule(){localRelocationSchedule=null;localRelocationDueLastAttempt=0;}\nfunction makeRelocationScheduleToken(){\n  if(globalThis.crypto?.randomUUID)return `rel-${crypto.randomUUID()}`;\n  const a=new Uint32Array(4);crypto.getRandomValues(a);\n  return `rel-${Date.now()}-${Array.from(a,n=>n.toString(36)).join("")}`;\n}\nfunction relocationRangeForIndex(index=relocationState.index){\n  return Number(index||0)===0\n    ? [Math.max(60,Number(relocationSettings.firstMin||1200)),Math.max(60,Number(relocationSettings.firstMax||1800))]\n    : [Math.max(60,Number(relocationSettings.intervalMin||900)),Math.max(60,Number(relocationSettings.intervalMax||1500))];\n}\nfunction freshRelocationSchedule(now,base=relocationState){\n  return {...base,active:false,scheduleToken:makeRelocationScheduleToken(),scheduleFrom:Number(now),startedAt:null,deadline:null,overtimeToken:""};\n}\nfunction privateRelocationStorageKey(token){\n  return `${PRIVATE_RELOCATION_STORAGE_PREFIX}:${window.BigWalkRooms?.getRoomCode?.()||"room"}:${token}`;\n}\nfunction ensureLocalRelocationSchedule(){\n  if(!isRoomHider()||relocationState.active||missionState.active)return null;\n  const token=String(relocationState.scheduleToken||"");if(!token)return null;\n  if(localRelocationSchedule?.token===token)return localRelocationSchedule;\n  const from=Number(relocationState.scheduleFrom);if(!Number.isFinite(from))return null;\n  const range=relocationRangeForIndex(relocationState.index),lo=Math.min(...range),hi=Math.max(...range),now=currentMatchSeconds();\n  let dueAt=Number.NaN;\n  try{\n    const saved=JSON.parse(localStorage.getItem(privateRelocationStorageKey(token))||"null");\n    if(saved&&saved.token===token&&Number(saved.from)===from&&Number.isFinite(Number(saved.dueAt)))dueAt=Number(saved.dueAt);\n  }catch{}\n  if(!Number.isFinite(dueAt)){\n    const minDue=from+lo,maxDue=from+hi;\n    if(now>=maxDue)dueAt=now;\n    else{const floor=Math.max(now,minDue);dueAt=floor+Math.random()*Math.max(0,maxDue-floor);}\n    dueAt=Math.max(now,Math.round(dueAt/15)*15);\n    try{localStorage.setItem(privateRelocationStorageKey(token),JSON.stringify({token,from,dueAt}));}catch{}\n  }\n  localRelocationSchedule={token,from,dueAt};\n  return localRelocationSchedule;\n}\nfunction privateRelocationRemaining(){\n  const schedule=ensureLocalRelocationSchedule();\n  return schedule?Math.max(0,Number(schedule.dueAt)-currentMatchSeconds()):Number.NaN;\n}\nfunction maybeSignalPrivateRelocationDue(){\n  if(!isRoomHider()||!roomMatchRunning()||hidingTimeRemaining()>.01||relocationState.active||missionState.active)return;\n  const schedule=ensureLocalRelocationSchedule();if(!schedule||currentMatchSeconds()+.01<Number(schedule.dueAt))return;\n  const existing=window.BigWalkRooms?.getHiderRelocationDueSignal?.();\n  if(existing&&String(existing.token||"")===schedule.token)return;\n  const now=Date.now();if(now-localRelocationDueLastAttempt<1000)return;localRelocationDueLastAttempt=now;\n  const fn=window.BigWalkRooms?.signalRelocationDue;\n  if(typeof fn!=="function"||window.BigWalkRooms?.getBuildId?.()!==REQUIRED_ROOMS_BUILD_ID)return;\n  Promise.resolve(fn(schedule.token)).catch(err=>{console.warn("Private relocation due signal failed",err);localRelocationDueLastAttempt=0;});\n}\nfunction relocationCellKey(x,y){return `${x},${y}`;}\nfunction buildRelocationPlan(start){\n''', 'private relocation helpers')

