# Replace host relocation scheduler: host reacts to Hider due signal, never owns a future exact timestamp.
s = sub_once(s, r'''async function maybeHostAdvanceRelocation\(\)\{.*?\n\}\nfunction updateRelocationUi\(\)\{.*?\n\}\n\nfunction showTab''', '''async function maybeHostAdvanceRelocation(){\n  if(!roomModeConnected()||!roomCanDriveRelocation()||relocationMutationBusy||!roomMatchRunning()||hidingTimeRemaining()>.01)return;\n  if(missionState.active&&!relocationState.active)return;\n  const now=currentMatchSeconds();\n  if(relocationState.active){\n    if(!currentRelocationOvertimeToken()){\n      relocationMutationBusy=true;\n      try{relocationState={...relocationState,overtimeToken:makeRelocationOvertimeToken()};await window.BigWalkRooms.pushGameState();}\n      finally{relocationMutationBusy=false;}\n      return;\n    }\n    const signal=window.BigWalkRooms?.getHiderRelocationSignal?.();\n    if(signal&&Number(signal.index)>=Number(relocationState.index)){\n      relocationMutationBusy=true;\n      try{\n        relocationState=freshRelocationSchedule(now,{...relocationState,lastResult:signal.result||"completed"});\n        resetLocalRelocationPlan();resetLocalRelocationSchedule();\n        await window.BigWalkRooms.pushGameState();\n      }finally{relocationMutationBusy=false;}\n    }\n    return;\n  }\n  if(!window.BigWalkRooms?.hasHider?.())return;\n  if(!String(relocationState.scheduleToken||"")){\n    relocationMutationBusy=true;\n    try{relocationState=freshRelocationSchedule(Number(relocationState.index||0)===0?0:now,relocationState);resetLocalRelocationSchedule();await window.BigWalkRooms.pushGameState();}\n    finally{relocationMutationBusy=false;}\n    return;\n  }\n  const due=window.BigWalkRooms?.getHiderRelocationDueSignal?.();\n  if(!due||String(due.token||"")!==String(relocationState.scheduleToken||""))return;\n  relocationMutationBusy=true;\n  try{\n    relocationState={active:true,index:Number(relocationState.index||0)+1,scheduleToken:"",scheduleFrom:null,startedAt:now,deadline:now+relocationSettings.window,lastResult:"",overtimeToken:makeRelocationOvertimeToken()};\n    resetLocalRelocationPlan();resetLocalRelocationSchedule();\n    await window.BigWalkRooms.pushGameState();\n  }finally{relocationMutationBusy=false;}\n}\nfunction updateRelocationUi(){\n  const section=document.getElementById("relocationGameSection"),headline=document.getElementById("relocationHeadline"),target=document.getElementById("relocationTarget"),progress=document.getElementById("relocationProgress"),message=document.getElementById("relocationMessage"),readyBtn=document.getElementById("relocationReadyBtn");\n  if(!section)return;\n  if(!roomModeConnected()||!isRoomHider()||!relocationState.active){section.style.display="none";return;}\n  section.style.display="block";section.classList.add("relocationActive");\n  readyBtn.style.display="none";readyBtn.disabled=true;readyBtn.textContent="Ready";\n  const now=currentMatchSeconds(),remaining=Math.max(0,Number(relocationState.deadline||now)-now);\n  headline.textContent=remaining>0?formatTime(remaining):"OVERTIME";\n  if(!liveMarker){target.textContent=`${relocationSettings.minDistance} units`;progress.textContent="Waiting for live tracker";message.textContent="Connect live location. Your coordinates stay local; only completion and intentional overtime reveal data are sent.";return;}\n  if(!localRelocationPlan){target.textContent="Calculating…";progress.textContent="—";message.textContent="Mapping the connected legal search area around your relocation start.";return;}\n  if(localRelocationPlan.invalid){target.textContent="—";progress.textContent="Start outside legal area";message.textContent="Move back inside the current valid search area so relocation can begin.";return;}\n  if(localRelocationPlan.skip){target.textContent="Skipped";progress.textContent=`Max ≈ ${Math.round(localRelocationPlan.maxDistance)} units`;message.textContent="The remaining connected legal area is too cramped for a meaningful relocation. Sending a skip result.";return;}\n  const d=Math.hypot(liveMarker.x-localRelocationPlan.start.x,liveMarker.y-localRelocationPlan.start.y),legal=pointInRelocationRegion(liveMarker,localRelocationPlan),ready=d>=localRelocationPlan.target&&legal;\n  target.textContent=`${Math.round(localRelocationPlan.target)} units${localRelocationPlan.target<relocationSettings.minDistance?" · scaled":""}`;\n  progress.textContent=`${Math.round(d)} / ${Math.round(localRelocationPlan.target)}${legal?"":" · outside connected legal area"}`;\n  readyBtn.style.display=(ready||localRelocationPlan.signaled)?"block":"none";readyBtn.disabled=!ready||localRelocationPlan.signaled;readyBtn.textContent=localRelocationPlan.signaled?"Ready — confirming…":"Ready";\n  message.textContent=localRelocationPlan.signaled?"Ready confirmed — waiting for the room to privately reroll the next relocation.":ready?"Minimum move reached. Keep searching if you want, then press Ready once you have a hiding spot.":"Displacement is measured from where this relocation started, not total distance traveled.";\n}\n\nfunction showTab''', 'replace relocation scheduler/ui', re.S)

# Shared room state migration/reset handling.
s = once(s, '''      if(game.relocationSettings&&typeof game.relocationSettings==="object")relocationSettings={...relocationSettings,...game.relocationSettings};\n      if(game.relocationState&&typeof game.relocationState==="object"){\n        const incoming={...relocationState,...game.relocationState};\n        if(Number(incoming.index)!==Number(relocationState.index)||!incoming.active)resetLocalRelocationPlan();\n        relocationState=incoming;\n      }\n''', '''      if(game.relocationSettings&&typeof game.relocationSettings==="object"){\n        const incomingSettings=game.relocationSettings;\n        relocationSettings={...relocationSettings,...incomingSettings};\n        if(!Number.isFinite(Number(incomingSettings.firstMin))&&Number.isFinite(Number(incomingSettings.firstAt)))relocationSettings.firstMin=relocationSettings.firstMax=Number(incomingSettings.firstAt);\n        if(!Number.isFinite(Number(incomingSettings.intervalMin))&&Number.isFinite(Number(incomingSettings.interval)))relocationSettings.intervalMin=relocationSettings.intervalMax=Number(incomingSettings.interval);\n        relocationSettings.firstMax=Math.max(Number(relocationSettings.firstMin),Number(relocationSettings.firstMax));\n        relocationSettings.intervalMax=Math.max(Number(relocationSettings.intervalMin),Number(relocationSettings.intervalMax));\n      }\n      if(game.relocationState&&typeof game.relocationState==="object"){\n        const incoming={...relocationState,...game.relocationState};\n        if(Number(incoming.index)!==Number(relocationState.index)||!incoming.active)resetLocalRelocationPlan();\n        if(String(incoming.scheduleToken||"")!==String(relocationState.scheduleToken||""))resetLocalRelocationSchedule();\n        relocationState=incoming;\n      }\n''', 'shared relocation migration')

