# Settings apply handler uses range validation and rerolls only when idle.
s = sub_once(s, r'''document\.getElementById\("applyRelocationSettingsBtn"\)\.onclick=\(\)=>\{.*?\n\};\n\ndocument\.getElementById\("fitBtn"\)\.onclick=fitMap;''', '''document.getElementById("applyRelocationSettingsBtn").onclick=()=>{\n  const v=document.getElementById("relocationSettingsValidation");v.textContent="";\n  if(roomModeConnected()&&!window.BigWalkRooms?.isHost?.()){v.textContent="Only the room host can change relocation settings.";return;}\n  const firstMin=+document.getElementById("relocationFirstMinMinutes").value,firstMax=+document.getElementById("relocationFirstMaxMinutes").value,repeatMin=+document.getElementById("relocationRepeatMinMinutes").value,repeatMax=+document.getElementById("relocationRepeatMaxMinutes").value,windowMin=+document.getElementById("relocationWindowMinutes").value,minDistance=+document.getElementById("relocationMinDistance").value,skipBelow=+document.getElementById("relocationSkipBelow").value;\n  if(![firstMin,firstMax,repeatMin,repeatMax,windowMin,minDistance,skipBelow].every(Number.isFinite)||firstMin<=0||firstMax<=0||repeatMin<=0||repeatMax<=0||windowMin<=0||minDistance<25||skipBelow<25){v.textContent="Use positive times and distances of at least 25 units.";return;}\n  if(firstMax<firstMin||repeatMax<repeatMin){v.textContent="Each maximum must be greater than or equal to its minimum.";return;}\n  if(skipBelow>minDistance){v.textContent="Skip-below distance cannot be larger than the normal relocation target.";return;}\n  relocationSettings={firstMin:firstMin*60,firstMax:firstMax*60,intervalMin:repeatMin*60,intervalMax:repeatMax*60,window:windowMin*60,minDistance,skipBelow};\n  if(!relocationState.active&&!missionState.active){relocationState=freshRelocationSchedule(currentMatchSeconds(),relocationState);resetLocalRelocationSchedule();}\n  clearSettingDraft(["relocationFirstMinMinutes","relocationFirstMaxMinutes","relocationRepeatMinMinutes","relocationRepeatMaxMinutes","relocationWindowMinutes","relocationMinDistance","relocationSkipBelow"]);\n  resetLocalRelocationPlan();updateRelocationSettingsInputs();renderMatchTimer();notifyRoomGameStateChanged();\n  v.style.color="#9ef1c2";v.textContent="Relocation settings applied; the next private trigger has been rerolled.";setTimeout(()=>{v.textContent="";v.style.color="";},1800);\n};\n\ndocument.getElementById("fitBtn").onclick=fitMap;''', 'relocation settings handler', re.S)

# Floating display buttons retain SVG icons and toggle visual pressed state.
s = once(s, '''document.getElementById("gridBtn").onclick=()=>{\n  showGrid=!showGrid;document.getElementById("gridBtn").textContent=showGrid?"Hide grid":"Show grid";draw();\n};\ndocument.getElementById("towerBtn").onclick=()=>{\n  showTowers=!showTowers;document.getElementById("towerBtn").textContent=showTowers?"Hide towers":"Show towers";draw();\n};\ndocument.getElementById("landmarkBtn").onclick=()=>{\n  showLandmarks=!showLandmarks;document.getElementById("landmarkBtn").textContent=showLandmarks?"Hide landmarks":"Show landmarks";draw();\n};\n''', '''function syncMapDisplayButtons(){\n  for(const [id,shown,label] of [["gridBtn",showGrid,"grid"],["towerBtn",showTowers,"towers"],["landmarkBtn",showLandmarks,"landmarks"]]){\n    const btn=document.getElementById(id);if(!btn)continue;btn.classList.toggle("displayActive",shown);btn.setAttribute("aria-pressed",String(shown));btn.title=`${shown?"Hide":"Show"} ${label}`;\n  }\n}\ndocument.getElementById("gridBtn").onclick=()=>{showGrid=!showGrid;syncMapDisplayButtons();draw();};\ndocument.getElementById("towerBtn").onclick=()=>{showTowers=!showTowers;syncMapDisplayButtons();draw();};\ndocument.getElementById("landmarkBtn").onclick=()=>{showLandmarks=!showLandmarks;syncMapDisplayButtons();draw();};\n''', 'map toggle handlers')

# Both floating docks must block map pointer capture.
s = once(s, '''const mapToolDock=document.getElementById("mapToolDock");\nmapToolDock.addEventListener("pointerdown",e=>e.stopPropagation());\nmapToolDock.addEventListener("pointerup",e=>e.stopPropagation());\n''', '''const mapToolDock=document.getElementById("mapToolDock"),mapDisplayDock=document.getElementById("mapDisplayDock");\nfor(const dock of [mapToolDock,mapDisplayDock]){dock.addEventListener("pointerdown",e=>e.stopPropagation());dock.addEventListener("pointerup",e=>e.stopPropagation());}\n''', 'map dock pointer events')

# Calibration legends no longer exist.
s = sub_once(s, r'''function populate\(\)\{.*?\n\}\n\ndocument\.querySelectorAll\("\.tabBtn"\)''', '''function populate(){\n  for(const sel of [document.getElementById("nearestTower"),document.getElementById("radarTower")]){\n    for(const name of Object.keys(towers)){const o=document.createElement("option");o.value=name;o.textContent=name;sel.appendChild(o);}\n  }\n  for(const sel of [document.getElementById("nearestLandmark"),document.getElementById("landmarkRadiusLandmark")]){\n    for(const name of Object.keys(landmarks)){const o=document.createElement("option");o.value=name;o.textContent=name;sel.appendChild(o);}\n  }\n}\n\ndocument.querySelectorAll(".tabBtn")''', 'populate without legends', re.S)

# Tick Hider's private clock independently of host scheduling.
